model PortForward {
  id         String @id @default(cuid())
  serverId   String
  server     Server @relation(fields: [serverId], references: [id], onDelete: Cascade)
  publicPort Int    @unique
  guestPort  Int
  protocol   String @default("tcp")
}

enum FirewallDirection {
  INBOUND
}

enum FirewallAction {
  ALLOW
  DENY
}

enum FirewallProtocol {
  TCP
  UDP
  ICMP
  ALL
}

 * PROVISION reported success anyway).
 *
 * SOURCED DIRECTLY from each family's `docker run -p ...` mapping in
 * prisma/catalog.ts / prisma/seed-wave1-games.ts / prisma/seed-wave2-games.ts —
 * these are the ONLY ports Docker actually exposes off the container, so they
 * are the only ports reachable from outside it. If a game's setup script ever
 * changes its `-p` mapping, this entry must change with it or the health check
 * will probe a port nothing forwards to.
 *
 * `protocol` is not always the game's own play port: several titles (valheim,
 * palworld, vrising, enshrouded, theforest, sonsoftheforest, bedrock) expose
 * ONLY a UDP port in their image — no TCP port is mapped at all, so there is
 * nothing a TCP connect could ever prove for them. Where an image also exposes
 * a TCP port (often RCON/query, e.g. rust's 28016, ark's 27020, factorio's
 * 27015) THAT port is used instead: a TCP handshake is verifiable with a plain
 * connect, and the process binding it is proof the game server itself came up,
 * which is exactly the class of bug this check exists to catch — even though
 * it isn't the port the player's game client uses to join.
 */
export const GAME_PORT: Record<GameFamily, { port: number; protocol: "tcp" | "udp" }> = {
  minecraft: { port: 25565, protocol: "tcp" },
  valheim: { port: 2456, protocol: "udp" }, // no tcp port mapped
  rust: { port: 28016, protocol: "tcp" }, // rcon tcp; 28015/udp is the join port
  palworld: { port: 8211, protocol: "udp" }, // no tcp port mapped
  cs2: { port: 27015, protocol: "tcp" },
  terraria: { port: 7777, protocol: "tcp" },
  ark: { port: 27020, protocol: "tcp" }, // rcon tcp; 7777/7778/27015 are udp
  satisfactory: { port: 7777, protocol: "tcp" }, // image maps 7777 as both tcp+udp
  projectzomboid: { port: 27015, protocol: "tcp" }, // rcon tcp; 16261/16262 are udp
  sdtd: { port: 26900, protocol: "tcp" }, // 26900 is mapped as both tcp+udp
  vrising: { port: 9876, protocol: "udp" }, // no tcp port mapped
  // Enshrouded is SINGLE-PORT: the current dedicated server binds only its
  // queryPort. Verified live 2026-09-07 on a fully-started server — its own
  // generated `enshrouded_server.json` carries a `queryPort` key and NO
  // `gamePort` key at all, the process bound udp:15637 and nothing on 15636,
  // and an A2S_INFO datagram to 15637 answered `ff ff ff ff 41 …` while 15636
  // was silent. The old 15636 here (the pre-2024 two-port scheme) meant the
  // provisioning health check probed a port nothing ever binds, so EVERY
  // Enshrouded order sat in "Installing the game…" for 45 minutes per attempt
  // and then failed — and the single forward handed to the customer was the
  // dead port.
  enshrouded: { port: 15637, protocol: "udp" }, // the server's queryPort is its only port
  factorio: { port: 27015, protocol: "tcp" }, // rcon tcp; 34197/udp is the join port
  gmod: { port: 27015, protocol: "tcp" },
  // Conan's image maps 7777 as both tcp+udp, but they are NOT the same
  // service on two protocols the way rust/ark/gmod are — Funcom's own
  // dedicated-server page (conanexiles.com/dedicated-servers, verified
  // 2026-09-24) says outright: "The primary port for players to connect is
  // 7777 (UDP)"; 7777/TCP is documented separately as "Mod downloads (PC
  // only)" — a real, different service, not dead weight. TCP stays the
  // GAME_PORT health-check port (mod-download service is real, so a TCP
  // connect is still genuine evidence the container booted); the join port is
  // overridden to UDP below. See GAME_JOIN_PORT_OVERRIDE's `conan` entry.
  conan: { port: 7777, protocol: "tcp" },
  unturned: { port: 27015, protocol: "udp" }, // UDP game: binds 27015/udp (game) + 27016/udp (query); the -p 27015/tcp publish is dead (nothing in the container listens on TCP), so a TCP check never passes
  theforest: { port: 27015, protocol: "udp" }, // no tcp port mapped
  sonsoftheforest: { port: 8766, protocol: "udp" }, // no tcp port mapped
  bedrock: { port: 19132, protocol: "udp" }, // RakNet — no tcp variant exists
  // ── Wave 3. dragonwilds/sunkenland/abioticfactor/corekeeper/icarus ports below are
  //    CONFIRMED against the real `-p ...` mapping in prisma/seed-wave3-games.ts
  //    (2026-08-31) — all four Wine-based/native images map UDP-only, so the health
  //    check probes the UDP game port. schedule1 stays unseeded (see below). ──
  schedule1: { port: 38465, protocol: "tcp" }, // UNVERIFIED: no official dedicated server exists (P2P/lobby) — stays unseeded
  dragonwilds: { port: 7777, protocol: "udp" }, // RS:Dragonwilds default game port (7778 = secondary)
  sunkenland: { port: 27015, protocol: "udp" }, // 27015 game + 27016 query, both udp
  abioticfactor: { port: 7777, protocol: "udp" }, // 7777 game + 27015 query, both udp
  corekeeper: { port: 27015, protocol: "udp" }, // 27015 + 27016 udp
  icarus: { port: 17777, protocol: "udp" }, // 17777 game + 27015 query, both udp
  // ── Wave 4 ports, confirmed against each `-p ...` mapping in
  //    prisma/seed-wave4-games.ts (2026-08-31). ──
  arkasa: { port: 27020, protocol: "tcp" }, // rcon tcp, same rationale as "ark" above; 7777/udp is the join port
  // Soulmask's echo/admin port is bound to LOOPBACK inside its container —
  // verified live 2026-09-08 off the running server's own namespace:
  // `0100007F:49C8` (127.0.0.1:18888). The `-p 18888:18888/tcp` publish is
  // therefore dead: docker-proxy accepts and the backend dial is refused, so an
  // external connect gets "Connection refused" and this check could never pass,
  // on any Soulmask order. Its real externally-bound ports are udp 8777 (game)
  // and udp 27015 (query), both on 0.0.0.0. Same shape as Unturned's dead TCP
  // publish — so, like Unturned, the check port is now the join port itself and
  // needs no override below. A UDP check is real evidence here because
  // provisioning also requires the socket to exist in the guest (see
      gamePlan: { select: { gameFamily: true } },
    },
  });
  if (!s) return null;

  // The NAT-forwarded connect IP is THIS server's own node's public IP, not
  // necessarily the platform's primary — same root cause as connectionTarget()
  // in lib/sftp.ts, for the same reason (vmids/port-forwards are per-node).
  const publicIp = s.node?.publicIp ?? process.env.PUBLIC_IP ?? "";

  // Match the port forward that actually serves the game's own port, not just
  // whichever one sorts first — a customer can add extra forwards (RCON web
  // UI, Dynmap, a Bedrock/Geyser port, ...) that must never be mistaken for
  // the game's real connect port here, since this result gates
  // `customDomainVerified`. Falls back to the first forward if none matches
  // (e.g. an unrecognized family) rather than reporting no connect info at all.
  const family = (s.gamePlan?.gameFamily ?? s.osTemplate?.family) as GameFamily | undefined;
  const expectedPort = family ? GAME_PORT[family]?.port : undefined;
  const gameForward = s.portForwards.find((f) => f.guestPort === expectedPort) ?? s.portForwards[0];
  const defaultPort = expectedPort ?? 25565;

  if (s.dedicatedIp) {
    // Dedicated IP has no NAT translation — the guest's own game port is what
    // players (and DNS) actually connect to.
    return { ip: s.dedicatedIp.address, port: gameForward?.guestPort ?? defaultPort };
  }

  if (gameForward) {
    return { ip: publicIp, port: gameForward.publicPort };
  }

