  }
  const min = Math.min(...guests);
  return guests.map((g) => g - min);
}

/**
 * Claim one consecutive block inside an already-open transaction holding the
 * IPAM lock. `public = base + (guest - minGuest)`. Exported for the repair
 * script and tests. `skipPorts` lets a caller treat a server's own current
 * block as free when relocating.
 */
export async function claimForwardBlockInTx(
  tx: Tx,
  range: IpamRange,
  serverId: string,
  specs: readonly ForwardSpec[],
  opts: { skipPorts?: ReadonlySet<number>; useReservations?: boolean } = {}
): Promise<number[]> {
  const offsets = blockOffsets(specs);
  const [servers, forwards] = await Promise.all([
    tx.server.findMany({
      where: { sshPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
      select: { sshPort: true },
    }),
    tx.portForward.findMany({
      where: { publicPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
      select: { publicPort: true },
    }),
  ]);
  const used = new Set<number>([
    ...servers.map((s) => s.sshPort!).filter((p) => p != null),
    ...forwards.map((f) => f.publicPort),
  ]);
  for (const p of opts.skipPorts ?? []) used.delete(p);
  const useRes = opts.useReservations !== false;
  const base = findContiguousBase(used, range.sshPortStart, range.sshPortEnd, offsets, (p) =>
    useRes && isReserved(`port:${p}`)
  );
  if (base === null) {
    throw new Error(
      `No free consecutive block of ${Math.max(...offsets) + 1} ports in ` +
        `${range.sshPortStart}-${range.sshPortEnd}` +
        (range.nodeId ? ` for node ${range.nodeId}` : "")
    );
  }
  const publicPorts = offsets.map((o) => base + o);
  for (let i = 0; i < specs.length; i++) {
    await tx.portForward.create({
      data: { serverId, publicPort: publicPorts[i], guestPort: specs[i].guestPort, protocol: specs[i].protocol },
    });
  }
  return publicPorts;
}

