import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { db } from "../lib/db";
import {
  planNatRules,
  reconcileNatChain,
  ruleSpec,
  type ForwardSource,
  type NatHost,
  type NatRule,
  type NatSyncResult,
} from "../lib/nat-rules";
import { agentEnsureChain, agentListChain, agentAddRule, agentDeleteRule, type AgentNode } from "../lib/node-agent";

const exec = promisify(execFile);

async function iptables(args: string[]) {
  await exec("iptables", args);
}

async function ensureChainLocal(chain: string) {
  try {
    await iptables(["-t", "nat", "-N", chain]);
  } catch {
    /* chain exists */
  }
  // Ensure PREROUTING jumps to our chain exactly once — this is the path for
  // EXTERNAL clients (real customers) reaching a NAT guest's forwarded port.
  try {
    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", chain]);
  } catch {
    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", chain]);
  }
  // Also jump from OUTPUT for HOST-LOCAL traffic aimed at our own public IP.
  // PREROUTING DNAT never fires for packets a process on THIS box originates, so
  // the platform's own ops that connect to <PUBLIC_IP>:<forwarded-port> — SSL
  // issuance, migration remediation, backups, the Claude backfill — were hitting
  // the host's own (empty) port and getting ECONNREFUSED for every NAT server.
  // Scoping the jump to `-d <PUBLIC_IP>` means only traffic addressed to the
  // public IP is redirected; host-local :port traffic to anything else is
  // untouched, and the shared DNAT rules only match ports that actually forward.
  const publicIp = (process.env.PUBLIC_IP ?? "").trim();
  if (publicIp) {
    try {
      await iptables(["-t", "nat", "-C", "OUTPUT", "-d", publicIp, "-j", chain]);
    } catch {
      await iptables(["-t", "nat", "-A", "OUTPUT", "-d", publicIp, "-j", chain]);
    }
  }
}

/**
 * The real, iptables-backed NatHost for the PRIMARY's own chain — the only
 * implementation production used before multi-node. The decision logic it is
 * handed to lives in lib/nat-rules.ts and is tested against an in-memory fake;
 * see the H5 incident note at the top of that file.
 */
function iptablesHost(chain: string): NatHost {
  return {
    ensureChain: () => ensureChainLocal(chain),
    listChain: async () => {
      const { stdout } = await exec("iptables", ["-t", "nat", "-S", chain]);
      return stdout;
    },
    addRule: (r: NatRule) => iptables(["-t", "nat", "-A", chain, ...ruleSpec(r)]),
    deleteRule: (r: NatRule) => iptables(["-t", "nat", "-D", chain, ...ruleSpec(r)]),
  };
}

/**
 * The remote, agent-backed NatHost for any non-primary node. Implements the
 * exact same NatHost seam over HTTPS — reconcileNatChain's tested
 * reconciliation logic runs unmodified against either implementation.
 */
function agentNatHost(node: AgentNode, chain: string): NatHost {
  return {
    ensureChain: () => agentEnsureChain(node, chain),
    listChain: () => agentListChain(node, chain),
    addRule: (r: NatRule) => agentAddRule(node, chain, r),
    deleteRule: (r: NatRule) => agentDeleteRule(node, chain, r),
  };
}

/** Dispatch: local iptables for the primary (the only node the worker itself
 *  runs on), the remote agent for everyone else. */
function natHostFor(node: { isPrimary: boolean } & AgentNode, chain: string): NatHost {
  return node.isPrimary ? iptablesHost(chain) : agentNatHost(node, chain);
}

/**
 * Reconcile every node's OWN NAT chain with the database, and verify each
 * result — one intent, one chain, one host PER NODE, never merged.
 *
 * Before multi-node this pulled every server platform-wide into a single
 * intent and always applied it to the local host's chain — harmless with one
 * node, but wrong the moment a second one exists: a node-2 server's forward
 * would be planned correctly and then installed on the PRIMARY's own
 * iptables, pointing at a private IP (10.20.1.x) the primary has no route to
 * — a rule that can never work, sitting in the wrong place. Servers are now
 * grouped by their own `nodeId` (falling back to the primary for the rare
 * legacy row with none, matching worker/index.ts's `nodeFor()` fallback) and
 * each node's chain is reconciled independently against ITS OWN NatHost.
 *
