 * server's game port was reachable by nobody until the customer manually
 * added a forward from the dashboard — found live via a real customer whose
 * Minecraft server had zero forwards and no dedicated IP, so its game port
 * had no path from any public IP at all. Dedicated-IP servers need no
 * forward (their guest port IS the public port) — callers should only call
 * this for the NAT case.
 */
export async function allocateGameForward(
  nodeId: string | null | undefined,
  serverId: string,
  guestPort: number,
  protocol: "tcp" | "udp" = "tcp"
): Promise<number> {
  const range = await ipamRange(nodeId);
  await probeAdvisoryLocks();

  let lastErr: unknown;
  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
    let port = 0;
    try {
      port = await db.$transaction(async (tx) => {
        await lockIpam(tx);
        const candidate = await pickFreePort(tx, range);
        await tx.portForward.create({
          data: { serverId, publicPort: candidate, guestPort, protocol },
        });
        return candidate;
      });
    } catch (e) {
      lastErr = e;
      if (isUniqueConflict(e)) continue;
      throw e;
    }
    reserve(`port:${port}`);
    return port;
  }
  throw new Error(
    `Game port forward allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
  );
}

