export type ForwardSpec = { guestPort: number; protocol: "tcp" | "udp" };

/**
 * PURE. Lowest `base` in [start, end] such that every `base + offset` is free.
 * Offsets need not be dense (a block may be sparse) but must be >= 0. Returns
 * null when no such base exists (range exhausted / too fragmented).
 */
 * from one atomic allocation when none of it exists yet; everything else (and
 * any leftover gap) is allocated one port at a time as before. Returns the
 * rows it created. Never throws for a single port: callers log and continue.
 */
export async function ensureGameForwards(
  nodeId: string | null | undefined,
  serverId: string,
  family: GameFamily
): Promise<{ guestPort: number; protocol: string; publicPort: number }[]> {
  const created: { guestPort: number; protocol: string; publicPort: number }[] = [];
  const have = async () =>
    new Set(
      (await db.portForward.findMany({ where: { serverId }, select: { guestPort: true, protocol: true } })).map(
        (f) => `${f.protocol}/${f.guestPort}`
      )
    );
  let existing = await have();
  const block = contiguousForwardPorts(family);
  if (block && block.every((p) => !existing.has(`${p.protocol}/${p.port}`))) {
    const pub = await allocateGameForwardBlock(
      nodeId,
      serverId,
      block.map((p) => p.port),
      block.map((p) => p.protocol)
    );
    block.forEach((p, i) => created.push({ guestPort: p.port, protocol: p.protocol, publicPort: pub[i] }));
    existing = await have();
  }
  for (const p of joinPortsFor(family)) {
    if (existing.has(`${p.protocol}/${p.port}`)) continue;
    const pub = await allocateGameForward(nodeId, serverId, p.port, p.protocol);
    created.push({ guestPort: p.port, protocol: p.protocol, publicPort: pub });
  }
  return created;
}

